CREATE DATABASE "sistema_ingressos";
USE "sistema_ingressos";

CREATE TABLE IF NOT EXISTS "cliente" (
	"id_cliente" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"nome" VARCHAR(255) NOT NULL,
	"email" VARCHAR(255) NOT NULL,
	PRIMARY KEY("id_cliente")
);

CREATE TABLE IF NOT EXISTS "ingresso" (
	"id_ingresso" INTEGER NOT NULL,
	"id_cliente" INTEGER NOT NULL,
	"id_evento" INTEGER NOT NULL,
	"status_ingresso" BOOLEAN NOT NULL,
	"nome_cliente" VARCHAR(255) NOT NULL,
	"data_evento" DATE NOT NULL,
	PRIMARY KEY("id_ingresso")
);

CREATE TABLE IF NOT EXISTS "evento" (
	"id_evento" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"titulo_evento" VARCHAR(255) NOT NULL,
	"quantidade_ingressos" INTEGER NOT NULL,
	"quantidade_disponivel" INTEGER NOT NULL,
	"quantidade_vendida" INTEGER NOT NULL,
	"capacidade_evento" INTEGER NOT NULL,
	"data_evento" DATE NOT NULL,
	PRIMARY KEY("id_evento")
);

ALTER TABLE "ingresso"
ADD FOREIGN KEY("id_cliente") REFERENCES "cliente"("id_cliente")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "ingresso"
ADD FOREIGN KEY("id_evento") REFERENCES "evento"("id_evento")
ON UPDATE NO ACTION ON DELETE NO ACTION;

